public sealed class OrderService(ILogger<OrderService> logger)
{
    public async Task PlaceAsync(Order order)
    {
        using var scope = logger.BeginScope(new Dictionary<string, object>
        {
            ["OrderId"] = order.Id,
            ["CustomerId"] = order.CustomerId,
        });

        logger.LogInformation("Placing order {OrderId} for {Amount}", order.Id, order.Amount);

        try
        {
            await SaveAsync(order);
            logger.LogInformation("Order {OrderId} placed", order.Id);
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Failed to place order {OrderId}", order.Id);
            throw;
        }
    }
}
